#!/usr/bin/env python3
"""Build sources/basboyun.json (Bas-Boyun kesitsel anatomi / head & neck cross-sectional anatomy) from hand-curated entries.
Citation, DOI, licence, version, title, journal, year, authors, verbatim captions and pixel sizes are read
from the downloaded bucket JSON/XML and image files in basboyun/images/raw/PMC<id>/ (never typed by hand).
Hand-written fields: section, use, topic, specimen, what_it_shows, labels_visible_in_image (checked visually),
key_findings (numbers quoted from the article text/abstract), clinical_relevance, notes.
Run: python3 -I scripts/build_basboyun_sources.py
"""
import json, pathlib, re, xml.etree.ElementTree as ET
from PIL import Image

ROOT = pathlib.Path(__file__).resolve().parent.parent
