out = []
for sec, use, topic, pmcid, figs, kf, cr, notes in E:
    d = RAW / pmcid
    js = sorted(d.glob(f"{pmcid}.*.json"))[-1]
    j = json.loads(js.read_text())
    ver = int(js.stem.rsplit(".", 1)[1])
    root = ET.parse(d / f"{pmcid}.{ver}.xml").getroot()
    meta = root.find(".//article-meta")
    au = [f"{t(c.find('name/surname'))} {t(c.find('name/given-names'))}" for c in meta.findall(".//contrib[@contrib-type='author']") if c.find("name") is not None]
    # year of publication = first 4-digit year after the journal abbreviation in the citation
    # (e.g. "J Med Ultrason (2001). 2022 Oct 26;..." -> 2022)
    year = re.search(r"\.\s*((?:19|20)\d{2})\b", j.get("citation", "")).group(1)
    capmap = {}
    for f in root.iter("fig"):
        for g in f.iter("graphic"):
            h = g.get(XL)
            capmap[h] = capmap[h.rsplit(".", 1)[0]] = (t(f.find("label")), t(f.find("caption")))
    fl = []
    for fn, spec, what, labs in figs:
        p = d / fn
        assert p.exists(), p
        lab, cap = capmap.get(fn) or capmap[fn.rsplit(".", 1)[0]]
        w, h = Image.open(p).size
        fl.append({"file": fn, "label": lab, "caption": cap, "specimen": spec, "what_it_shows": what,
                   "labels_visible_in_image": labs, "pixels": f"{w}x{h}",
                   "local_path": str(p.relative_to(ROOT))})
    out.append({"section": sec, "use": use, "topic": topic, "pmcid": pmcid, "version": ver, "doi": j.get("doi"),
                "citation": j.get("citation"), "title": t(meta.find(".//article-title")),
                "authors": ", ".join(au[:3]) + (" et al." if len(au) > 3 else ""), "year": year,
                "journal": t(root.find(".//journal-title")), "license_code": j.get("license_code"),
                "figures": fl, "key_findings": kf, "clinical_relevance": cr, "notes": notes})

# every downloaded image must be referenced exactly once
used = {f["local_path"] for e in out for f in e["figures"]}
disk = {str(p.relative_to(ROOT)) for p in RAW.glob("*/*") if p.suffix.lower() in (".jpg", ".jpeg", ".png", ".gif", ".tif")}
assert used == disk, (disk - used, used - disk)

(ROOT / "sources/basboyun.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n")
print(len(out), "entries;", len({e['pmcid'] for e in out}), "articles;", sum(len(e["figures"]) for e in out), "figures")
